CREATE TABLE IF NOT EXISTS "film" ("film_id" integer primary key autoincrement not null, "title" varchar not null, "description" text, "release_year" integer, "language_id" integer not null, "original_language_id" integer, "rental_duration" integer not null default ('3'), "rental_rate" numeric not null default ('4.99'), "length" integer, "replacement_cost" numeric not null default ('19.99'), "rating" varchar not null default ('G'), "special_features" text, "last_update" datetime not null default (CURRENT_TIMESTAMP), "imdb_id" varchar, "poster_url" varchar, "imdb_rating" numeric, "imdb_votes" integer, "metascore" integer, "plot" text, "awards" varchar, "box_office" varchar, "production" varchar, "website" varchar, "writers" text, "countries" text, "imported_from_omdb" tinyint(1) not null default ('0'), "category_id" integer, foreign key("original_language_id") references language("language_id") on delete set null on update no action, foreign key("language_id") references language("language_id") on delete restrict on update no action, foreign key("category_id") references "category"("category_id") on delete set null);
INSERT INTO film VALUES(1,'The Godfather','The Godfather "Don" Vito Corleone is the head of the Corleone mafia family in New York. He is at the event of his daughter''s wedding. Michael, Vito''s youngest son and a decorated WW II Marine is also present at the wedding. Michael seems to be uninterested in being a part of the family business. Vito is a powerful man, and is kind to all those who give him respect but is ruthless against those who do not. But when a powerful and treacherous rival wants to sell drugs and needs the Don''s influence for the same, Vito refuses to do it. What follows is a clash between Vito''s fading old values and the new ways which may cause Michael to do the thing he was most reluctant in doing and wage a mob war against all the other mafia families which could tear the Corleone family apart.',1972,1,1,3,4.99000000000000021,175,19.9899999999999984,'R',NULL,'2025-10-13 22:40:49','tt0068646','https://m.media-amazon.com/images/M/MV5BNGEwYjgwOGQtYjg5ZS00Njc1LTk2ZGEtM2QwZWQ2NjdhZTE5XkEyXkFqcGc@._V1_SX300.jpg',9.19999999999999928,2160424,100,'The Godfather "Don" Vito Corleone is the head of the Corleone mafia family in New York. He is at the event of his daughter''s wedding. Michael, Vito''s youngest son and a decorated WW II Marine is also present at the wedding. Michael seems to be uninterested in being a part of the family business. Vito is a powerful man, and is kind to all those who give him respect but is ruthless against those who do not. But when a powerful and treacherous rival wants to sell drugs and needs the Don''s influence for the same, Vito refuses to do it. What follows is a clash between Vito''s fading old values and the new ways which may cause Michael to do the thing he was most reluctant in doing and wage a mob war against all the other mafia families which could tear the Corleone family apart.','Won 3 Oscars. 31 wins & 31 nominations total','$136,381,073','N/A',NULL,'["Mario Puzo","Francis Ford Coppola"]','["United States"]',1,1);
INSERT INTO film VALUES(2,'Tron: Legacy','Sam Flynn, the tech-savvy 27-year-old son of Kevin Flynn, looks into his father''s disappearance and finds himself pulled into the same world of fierce programs and gladiatorial games where his father has been living for 20 years. Along with Kevin''s loyal confidant Quorra, father and son embark on a life-and-death journey across a visually-stunning cyber universe that has become far more advanced and exceedingly dangerous. Meanwhile, the malevolent program CLU, who dominates the digital world, plans to invade the real world and will stop at nothing to prevent their escape.',2010,1,1,3,4.99000000000000021,125,19.9899999999999984,'PG',NULL,'2025-10-13 22:41:02','tt1104001','https://m.media-amazon.com/images/M/MV5BMTk4NTk4MTk1OF5BMl5BanBnXkFtZTcwNTE2MDIwNA@@._V1_SX300.jpg',6.79999999999999982,372296,49,'Sam Flynn, the tech-savvy 27-year-old son of Kevin Flynn, looks into his father''s disappearance and finds himself pulled into the same world of fierce programs and gladiatorial games where his father has been living for 20 years. Along with Kevin''s loyal confidant Quorra, father and son embark on a life-and-death journey across a visually-stunning cyber universe that has become far more advanced and exceedingly dangerous. Meanwhile, the malevolent program CLU, who dominates the digital world, plans to invade the real world and will stop at nothing to prevent their escape.','Nominated for 1 Oscar. 10 wins & 52 nominations total','$172,062,763','N/A',NULL,'["Edward Kitsis","Adam Horowitz","Brian Klugman"]','["United States","India","United Kingdom","Mexico","Japan","Canada"]',1,2);
INSERT INTO film VALUES(3,'Goodfellas','Henry Hill might be a small time gangster, who may have taken part in a robbery with Jimmy Conway and Tommy De Vito, two other gangsters who might have set their sights a bit higher. His two partners could kill off everyone else involved in the robbery, and slowly start to think about climbing up through the hierarchy of the Mob. Henry, however, might be badly affected by his partners'' success, but will he consider stooping low enough to bring about the downfall of Jimmy and Tommy?',1990,1,1,3,4.99000000000000021,145,19.9899999999999984,'R',NULL,'2025-10-13 22:41:18','tt0099685','https://m.media-amazon.com/images/M/MV5BN2E5NzI2ZGMtY2VjNi00YTRjLWI1MDUtZGY5OWU1MWJjZjRjXkEyXkFqcGc@._V1_SX300.jpg',8.69999999999999929,1350647,92,'Henry Hill might be a small time gangster, who may have taken part in a robbery with Jimmy Conway and Tommy De Vito, two other gangsters who might have set their sights a bit higher. His two partners could kill off everyone else involved in the robbery, and slowly start to think about climbing up through the hierarchy of the Mob. Henry, however, might be badly affected by his partners'' success, but will he consider stooping low enough to bring about the downfall of Jimmy and Tommy?','Won 1 Oscar. 44 wins & 38 nominations total','$46,909,721','N/A',NULL,'["Nicholas Pileggi","Martin Scorsese"]','["United States"]',1,3);
